// queueAttempt is private to one actual runner invocation. Its row may be
// refreshed or removed while the runner is still returning. All mutable
// fields, and the running/attempts maps, are protected by Queue.mu.
type queueAttempt struct {
	job            Job
	ctx            context.Context
	cancel         context.CancelFunc
	retryRequested bool
	removed        bool
}

// Queue is the persistent work queue. One per SDK.

