func (q *Queue) upsert(ctx context.Context, job Job, mod query.ModifyFunc, retry bool) error {
	if job.Kind != KindDurable && job.Kind != KindPin {
		return fmt.Errorf("filestatus: unknown job kind %q", job.Kind)
	}
	if job.SpaceId == "" || job.FileId == "" {
		return errors.New("filestatus: spaceId and fileId required")
	}
	q.mu.Lock()
	_, err := q.coll.UpsertId(ctx, job.id(), mod)
	if err == nil && retry {
		if attempt := q.attempts[job.id()]; attempt != nil && !attempt.removed {
			attempt.retryRequested = true
		}
	}
	q.mu.Unlock()
	if err != nil {
		return err
	}
	q.notify(job, false)
	return nil
}

