func (q *Queue) Remove(ctx context.Context, kind, spaceId, fileId string) error {
	job := Job{Kind: kind, SpaceId: spaceId, FileId: fileId}
	q.mu.Lock()
	err := q.coll.DeleteId(ctx, job.id())
	if err == nil || errors.Is(err, anystore.ErrDocNotFound) {
		if attempt := q.attempts[job.id()]; attempt != nil {
			// Keep the running-ID fence until this callback actually returns.
			// A re-enqueued row belongs to later work, not this attempt.
			attempt.removed = true
		}
	}
	if cancel := q.running[job.id()]; cancel != nil {
		cancel()
	}
	q.mu.Unlock()
	if err != nil && !errors.Is(err, anystore.ErrDocNotFound) {
		return err
	}
	if err == nil {
		q.notify(job, true)
	}
	return nil
}

