// dispatchDue acquires capacity before selecting and claiming current work.
// A refresh cannot be lost between the due-row read and its running fence.
func (q *Queue) dispatchDue() {
	for {
		select {
		case q.slots <- struct{}{}:
		case <-q.ctx.Done():
			return
		}
		attempt, ok := q.nextDue()
		if !ok {
			<-q.slots
			return
		}
		q.wg.Add(1)
		go func() {
			defer q.wg.Done()
			q.runOne(attempt)
			attempt.cancel()
			q.mu.Lock()
			if q.attempts[attempt.job.id()] == attempt {
				delete(q.attempts, attempt.job.id())
				delete(q.running, attempt.job.id())
			}
			q.mu.Unlock()
			<-q.slots
			q.Kick()
		}()
	}
}

