// nextDue selects and claims a current due row in one critical section.
// Kinds alternate when both are due. The caller already owns a worker slot.
func (q *Queue) nextDue() (*queueAttempt, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.ctx.Err() != nil {
		return nil, false
	}
	now := float64(time.Now().Unix())
	filter := query.Key{Path: []string{fieldNext}, Filter: query.NewComp(query.CompOpLte, now)}
	iter, err := q.coll.Find(filter).Limit(dueBatch).Iter(q.ctx)
	if err != nil {
		return nil, false
	}
	var due []Job
	for iter.Next() {
		doc, err := iter.Doc()
		if err != nil {
			break
		}
		due = append(due, jobFromValue(doc.Value()))
	}
	_ = iter.Close()

	var pick *Job
	for i := range due {
		if _, busy := q.running[due[i].id()]; busy {
			continue
		}
		if due[i].Kind != q.lastKind {
			pick = &due[i]
			break
		}
		if pick == nil {
			pick = &due[i]
		}
	}
	if pick == nil {
		return nil, false
	}
	ctx, cancel := context.WithTimeout(q.ctx, jobTimeout(pick.Kind))
	attempt := &queueAttempt{job: *pick, ctx: ctx, cancel: cancel}
	q.running[pick.id()] = cancel
	q.attempts[pick.id()] = attempt
	q.lastKind = pick.Kind
	return attempt, true
